public Page<ExhibitVisitRank> findTopVisitedExhibits(
        LocalDateTime from,
        LocalDateTime to,
        int pageIndex,
        int pageSize
) {
    VisitTable v = VisitTable.$;
    ExhibitTable e = v.exhibit();
    MuseumTable m = e.museum();

    ConfigurableRootQuery<VisitTable, ExhibitVisitRank> query =
            sqlClient
                    .createQuery(v)
                    .where(v.visitedTime().ge(from))
                    .where(v.visitedTime().lt(to))
                    .groupBy(e.id(), e.name(), m.name())
                    .orderBy(count(v.id()).desc())
                    .select(
                            Projections.constructor(
                                    ExhibitVisitRank.class,
                                    e.id(),
                                    e.name(),
                                    m.name(),
                                    count(v.id())
                            )
                    );

    return query.fetchPage(pageIndex, pageSize);
}
